fn path_only(path: &str) -> &str {
    path.split('?').next().unwrap_or(path)
}

/// May an App's gateway link serve `method path` (exact match)?
pub fn link_allows_http(method: &str, path: &str) -> bool {
    let p = path_only(path);
    let m = method.to_ascii_uppercase();
    LINK_HTTP.iter().any(|(am, ap)| *am == m.as_str() && *ap == p)
}

/// May the browser helper forward `method path` (exact match)?
pub fn helper_allows_http(method: &str, path: &str) -> bool {
    let p = path_only(path);
    let m = method.to_ascii_uppercase();
    HTTP_ALLOWLIST.iter().any(|(am, ap)| *am == m.as_str() && *ap == p)
}

/// The query parameter an App-facing socket must carry, if `path` is one.
pub fn ws_param(path: &str) -> Option<&'static str> {
    let p = path_only(path);
    WS_ALLOWLIST.iter().find(|(wp, _)| *wp == p).map(|(_, param)| *param)
}

/// The catalog verb an App-facing `method path` (or `WS path`) runs.
pub fn verb_for(method: &str, path: &str) -> Option<&'static str> {
    let p = path_only(path);
    let m = method.to_ascii_uppercase();
    let m = if m == "HEAD" { "GET".to_string() } else { m };
    VERBS.iter().find(|(vm, vp, _, _)| *vm == m.as_str() && *vp == p).map(|(_, _, v, _)| *v)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_doors_split_the_one_table() {
        assert!(link_allows_http("GET", "/cli/thread"));
        assert!(link_allows_http("get", "/cli/thread?conversation=x"));
        assert!(link_allows_http("HEAD", "/cli/thread"));
        assert!(link_allows_http("POST", "/cli/thread/post"));
        assert!(!link_allows_http("GET", "/cli/thread/post"), "exact method");
        let on_link = |p: &str| link_allows_http("GET", p) || link_allows_http("POST", p);
        let on_helper = |p: &str| helper_allows_http("GET", p) || helper_allows_http("POST", p);
        for p in HELPER_ONLY_HTTP {
            assert!(!on_link(p) && on_helper(p), "{p} is the helper's alone");
        }
        for p in LINK_ONLY_HTTP {
            assert!(on_link(p) && !on_helper(p), "{p} is the link's alone");
        }
        assert!(HELPER_ONLY_HTTP.contains(&"/cli/skin/password/change"));
        assert!(LINK_ONLY_HTTP.contains(&"/cli/skin/login"));
        for never in ["/cli/auth/login", "/cli/sessions/events", "/cli/app/deploy", "/cli/skin/users/rooms", "/v1/sandboxes", "/cli/vault/get"] {
            assert!(!link_allows_http("GET", never) && !link_allows_http("POST", never), "{never}");
            assert!(!helper_allows_http("GET", never) && !helper_allows_http("POST", never), "{never}");
        }
        assert_eq!(ws_param("/cli/overlay/events?conversation=a"), Some("conversation"));
        assert_eq!(ws_param("/cli/sessions/events"), None);
        for (m, p) in HTTP_ALLOWLIST.iter().chain(LINK_HTTP.iter()) {
            assert!(p.starts_with("/cli/"), "{m} {p}");
            assert!(matches!(*m, "GET" | "HEAD" | "POST"), "{m} {p}");
            assert!(verb_for(m, p).is_some(), "{m} {p} names its verb");
        }
        assert_eq!(verb_for("HEAD", "/cli/thread"), Some("thread.page"));
        assert_eq!(verb_for("WS", "/cli/overlay/events"), Some("thread.events"));
    }
}
